import React, { useState, useContext } from 'react';
import { AuthContext } from '../AuthContext';
import './Auth.css';

function Register({ onSwitchToLogin }) {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phone_number: '',
    address: '',
    neighborhood: ''
  });
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const { register } = useContext(AuthContext);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    if (formData.password.length < 6) {
      setMessage('❌ Senha deve ter no mínimo 6 caracteres');
      setLoading(false);
      return;
    }

    const result = await register(
      formData.name,
      formData.email,
      formData.password,
      formData.phone_number,
      formData.address,
      formData.neighborhood
    );

    if (result.success) {
      setMessage('✅ Cadastro realizado com sucesso!');
      setTimeout(() => {
        window.location.reload();
      }, 1500);
    } else {
      setMessage(`❌ ${result.error}`);
    }
    setLoading(false);
  };

  return (
    <div className="auth-container">
      <div className="auth-box">
        <h1>🛒 EMPÓRIO BRUMADO</h1>
        <h2>Cadastro</h2>

        {message && <div className={`auth-message ${message.includes('✅') ? 'success' : 'error'}`}>{message}</div>}

        <form onSubmit={handleRegister}>
          <input
            type="text"
            name="name"
            placeholder="Nome completo"
            value={formData.name}
            onChange={handleChange}
            className="auth-input"
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            className="auth-input"
            required
          />
          <input
            type="tel"
            name="phone_number"
            placeholder="Telefone (ex: 11999999999)"
            value={formData.phone_number}
            onChange={handleChange}
            className="auth-input"
            required
          />
          <input
            type="text"
            name="address"
            placeholder="Endereço completo"
            value={formData.address}
            onChange={handleChange}
            className="auth-input"
            required
          />
          <input
            type="text"
            name="neighborhood"
            placeholder="Bairro"
            value={formData.neighborhood}
            onChange={handleChange}
            className="auth-input"
            required
          />
          <input
            type="password"
            name="password"
            placeholder="Senha (mín. 6 caracteres)"
            value={formData.password}
            onChange={handleChange}
            className="auth-input"
            required
          />
          <button type="submit" className="auth-btn" disabled={loading}>
            {loading ? 'Cadastrando...' : 'Cadastrar'}
          </button>
        </form>

        <p className="auth-switch">
          Já tem conta? <button onClick={onSwitchToLogin} className="link-btn">Faça login aqui</button>
        </p>
      </div>
    </div>
  );
}

export default Register;
